def as_card(row):
    from .inspiration_hanja import annotate
    return annotate(dict(zip(('category','text','source','english','explanation','reflection'),row)))


def render(card):
    return '\n\n'.join(x for x in (f"[{card['category']}] {card['text']}",card['english'],card['explanation'],'생각해 보기: '+card['reflection'],'출처: '+card['source']) if x)
